package horizon.observatory.acquisition.base

import horizon.observatory.domain.model.RawObservation
import kotlinx.coroutines.channels.SendChannel
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import java.util.concurrent.atomic.AtomicReference

/**
 * Non-blocking accounting for one platform acquisition source.
 *
 * These counters describe only callbacks and observations visible to Horizon. They do not
 * estimate events generated by a receiver or Android before this source received a callback.
 */
internal class AcquisitionDiagnostics(
    val sourceName: String,
    val sessionId: String = "UNASSIGNED",
) {
    private val callbacks = AtomicLong()
    private val callbacksInFlight = AtomicLong()
    private val expected = AtomicLong()
    private val constructed = AtomicLong()
    private val attempts = AtomicLong()
    private val accepted = AtomicLong()
    private val capacityRejected = AtomicLong()
    private val closedRejected = AtomicLong()
    private val constructionFailed = AtomicLong()
    private val callbackDurationTotal = AtomicLong()
    private val callbackDurationMax = AtomicLong()
    private val lastFailure = AtomicReference<String?>(null)
    private val byType = ConcurrentHashMap<String, TypeCounters>()

    /** Records one callback batch and the number of rows it should attempt to emit. */
    fun callbackStarted(expectedObservations: Int = 0): Long {
        callbacks.incrementAndGet()
        callbacksInFlight.incrementAndGet()
        if (expectedObservations > 0) expected.addAndGet(expectedObservations.toLong())
        return System.nanoTime()
    }

    /** One callback that is known to produce exactly one observation row. */
    fun recordSingleCallback(block: () -> RawObservation, channel: SendChannel<RawObservation>): Boolean {
        val started = callbackStarted(expectedObservations = 1)
        return try {
            offer(channel, block)
        } finally {
            callbackFinished(started)
        }
    }

    fun callbackFinished(startNanos: Long) {
        callbacksInFlight.updateAndGet { current -> (current - 1L).coerceAtLeast(0L) }
        val elapsed = (System.nanoTime() - startNanos).coerceAtLeast(0L)
        callbackDurationTotal.addAndGet(elapsed)
        callbackDurationMax.accumulateAndGet(elapsed) { current, next -> maxOf(current, next) }
    }

    /**
     * Builds an observation, attempts a non-suspending send, and records the admission result.
     * Construction failures and channel closure are kept separate from buffer-capacity loss.
     */
    fun offer(channel: SendChannel<RawObservation>, construct: () -> RawObservation): Boolean {
        val observation = try {
            construct()
        } catch (failure: Exception) {
            constructionFailed.incrementAndGet()
            lastFailure.set(failure.javaClass.name)
            return false
        }

        constructed.incrementAndGet()
        val type = byType.computeIfAbsent(observation.type.name) { TypeCounters(it) }
        type.constructed.incrementAndGet()
        attempts.incrementAndGet()
        type.attempts.incrementAndGet()

        val result = channel.trySend(observation)
        return if (result.isSuccess) {
            accepted.incrementAndGet()
            type.accepted.incrementAndGet()
            true
        } else {
            if (result.isClosed) {
                closedRejected.incrementAndGet()
                type.closedRejected.incrementAndGet()
                lastFailure.set("CHANNEL_CLOSED")
            } else {
                capacityRejected.incrementAndGet()
                type.capacityRejected.incrementAndGet()
                lastFailure.set("CHANNEL_CAPACITY")
            }
            false
        }
    }

    fun snapshot(): AcquisitionDiagnosticsSnapshot {
        val types = byType.values.map { it.snapshot() }.sortedBy { it.observationType }
            .associateBy { it.observationType }
        return AcquisitionDiagnosticsSnapshot(
            sourceName = sourceName,
            sessionId = sessionId,
            callbackEventsReceived = callbacks.get(),
            callbackEventsInFlight = callbacksInFlight.get(),
            expectedObservations = expected.get(),
            observationsConstructed = constructed.get(),
            sendAttempts = attempts.get(),
            sendAccepted = accepted.get(),
            sendRejectedCapacity = capacityRejected.get(),
            sendRejectedClosed = closedRejected.get(),
            constructionFailures = constructionFailed.get(),
            callbackDurationTotalNs = callbackDurationTotal.get(),
            callbackDurationMaxNs = callbackDurationMax.get(),
            lastFailure = lastFailure.get(),
            observationsByType = types,
        )
    }

    private class TypeCounters(val observationType: String) {
        val constructed = AtomicLong()
        val attempts = AtomicLong()
        val accepted = AtomicLong()
        val capacityRejected = AtomicLong()
        val closedRejected = AtomicLong()

        fun snapshot() = AcquisitionObservationTypeSnapshot(
            observationType = observationType,
            observationsConstructed = constructed.get(),
            sendAttempts = attempts.get(),
            sendAccepted = accepted.get(),
            sendRejectedCapacity = capacityRejected.get(),
            sendRejectedClosed = closedRejected.get(),
        )
    }
}

internal data class AcquisitionObservationTypeSnapshot(
    val observationType: String,
    val observationsConstructed: Long,
    val sendAttempts: Long,
    val sendAccepted: Long,
    val sendRejectedCapacity: Long,
    val sendRejectedClosed: Long,
)

internal data class AcquisitionDiagnosticsSnapshot(
    val sourceName: String,
    val sessionId: String,
    val callbackEventsReceived: Long,
    val callbackEventsInFlight: Long,
    val expectedObservations: Long,
    val observationsConstructed: Long,
    val sendAttempts: Long,
    val sendAccepted: Long,
    val sendRejectedCapacity: Long,
    val sendRejectedClosed: Long,
    val constructionFailures: Long,
    val callbackDurationTotalNs: Long,
    val callbackDurationMaxNs: Long,
    val lastFailure: String?,
    val observationsByType: Map<String, AcquisitionObservationTypeSnapshot>,
)
